import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Box, ButtonIcon, IconName } from '@metamask/design-system-react';
import {
  FormTextField,
  FormTextFieldSize,
  InputType,
} from '../../component-library';
import { useI18nContext } from '../../../hooks/useI18nContext';
import { PASSWORD_MIN_LENGTH } from '../../../helpers/constants/common';

type PasswordFormProps = {
  onChange: (password: string) => void;
  pwdInputTestId?: string;
  confirmPwdInputTestId?: string;
  disabled?: boolean;
};

export function computeMismatchError(
  password: string,
  confirmPassword: string,
): boolean {
  return (
    confirmPassword.length >= PASSWORD_MIN_LENGTH &&
    confirmPassword.length >= password.length &&
    password !== confirmPassword
  );
}

export default function PasswordForm({
  onChange,
  pwdInputTestId,
  confirmPwdInputTestId,
  disabled = false,
}: PasswordFormProps) {
  const t = useI18nContext();

  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const [confirmPassword, setConfirmPassword] = useState('');
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [confirmPasswordError, setConfirmPasswordError] = useState('');
  const [passwordLengthError, setPasswordLengthError] = useState(false);

  const confirmPasswordRef = useRef<HTMLInputElement>(null);

  const handlePasswordKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        confirmPasswordRef.current?.focus();
      }
    },
    [],
  );

  const handlePasswordChange = useCallback(
    (passwordInput: string) => {
      const confirmError = computeMismatchError(passwordInput, confirmPassword)
        ? t('passwordsDontMatch')
        : '';

      setPassword(passwordInput);

      setConfirmPasswordError(confirmError);
      setPasswordLengthError(false);
    },
    [confirmPassword, t],
  );

  const handleConfirmPasswordChange = useCallback(
    (confirmPasswordInput: string) => {
      const error = computeMismatchError(password, confirmPasswordInput)
        ? t('passwordsDontMatch')
        : '';

      setConfirmPassword(confirmPasswordInput);
      setConfirmPasswordError(error);
    },
    [password, t],
  );

  useEffect(() => {
    if (
      password.length >= PASSWORD_MIN_LENGTH &&
      confirmPassword.length >= PASSWORD_MIN_LENGTH &&
      password === confirmPassword
    ) {
      onChange(password);
    } else {
      onChange('');
    }
  }, [password, confirmPassword, onChange]);

  const handlePasswordBlur = useCallback(() => {
    const passwordLength = password.length;
    if (passwordLength > 0 && passwordLength < PASSWORD_MIN_LENGTH) {
      setPasswordLengthError(true);
    } else {
      setPasswordLengthError(false);
    }
  }, [password.length]);

  return (
    <Box>
      <FormTextField
        label={t('newPasswordCreate')}
        id="create-password-new"
        autoFocus
        autoComplete
        size={FormTextFieldSize.Lg}
        value={password}
        disabled={disabled}
        inputProps={{
          'data-testid': pwdInputTestId || 'create-password-new-input',
          type: showPassword ? InputType.Text : InputType.Password,
          onKeyDown: handlePasswordKeyDown,
        }}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          handlePasswordChange(e.target.value);
        }}
        helpTextProps={{
          className: 'text-alternative',
          'data-testid': 'short-password-error',
        }}
        helpText={t('passwordNotLongEnough')}
        onBlur={handlePasswordBlur}
        error={passwordLengthError}
        endAccessory={
          <ButtonIcon
            iconName={showPassword ? IconName.EyeSlash : IconName.Eye}
            data-testid="show-password"
            type="button"
            onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
              e.stopPropagation();
              setShowPassword(!showPassword);
            }}
            ariaLabel={
              showPassword ? t('passwordToggleHide') : t('passwordToggleShow')
            }
          />
        }
      />

      <FormTextField
        label={t('confirmPassword')}
        id="create-password-confirm"
        autoComplete
        marginTop={4}
        size={FormTextFieldSize.Lg}
        error={Boolean(confirmPasswordError)}
        disabled={disabled}
        helpTextProps={{
          'data-testid': 'confirm-password-error',
        }}
        helpText={confirmPasswordError}
        value={confirmPassword}
        inputRef={confirmPasswordRef}
        inputProps={{
          'data-testid':
            confirmPwdInputTestId || 'create-password-confirm-input',
          type: showConfirmPassword ? InputType.Text : InputType.Password,
        }}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          handleConfirmPasswordChange(e.target.value);
        }}
        endAccessory={
          <ButtonIcon
            iconName={showConfirmPassword ? IconName.EyeSlash : IconName.Eye}
            data-testid="show-confirm-password"
            type="button"
            onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
              e.stopPropagation();
              setShowConfirmPassword(!showConfirmPassword);
            }}
            ariaLabel={
              showConfirmPassword
                ? t('passwordToggleHide')
                : t('passwordToggleShow')
            }
          />
        }
      />
    </Box>
  );
}
